using GraphApi.Models.SGR.Menus;namespace GraphApi.Services.SGR.Menus{    /// <summary>    /// Define las operaciones de negocio y persistencia para Menus.    /// </summary>    public interface IMenusService    {        /// <summary>        /// Obtiene la lista de Menus con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadMenus>> GetMenus(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Menus con filtros opcionales.        /// </summary>        /// <param name="menuID">Filtro opcional para MenuID.</param>        /// <param name="tituloMenu">Filtro opcional para TituloMenu.</param>        /// <param name="ruta">Filtro opcional para Ruta.</param>        /// <param name="icono">Filtro opcional para Icono.</param>        /// <param name="orden">Filtro opcional para Orden.</param>        /// <param name="padreMenuID">Filtro opcional para PadreMenuID.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetMenusDynamic(            int? menuID,            string? tituloMenu,            string? ruta,            string? icono,            int? orden,            int? padreMenuID,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Menu.        /// </summary>        /// <param name="objInput">Datos para crear el Menu.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadMenus> CreateMenus(            clCreateMenus objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Menu.        /// </summary>        /// <param name="objInput">Datos para actualizar el Menu, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadMenus?> UpdateMenus(            clUpdateMenus objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Menu por su ID.        /// </summary>        /// <param name="nMenusID">ID del Menu a eliminar.</param>        Task<bool> DeleteMenus(int nMenusID);    }}